childCounts.source:
type Item = { name:string }
type Panel = { content items:Item+ }

let kids(): Item+ = { <Item name="k" /> }

let root(wide:bool, names:string+, n:int) =
  <Panel>
    <Item name="x" />
    // A note is not a child.
    if wide {
      <Item name="b" />
      <Item name="c" />
    } else {
      <Item name="d" />
    }
    for title in names {
      <Item name={title} />
    }
    if n is {
      0 => <Item name="zero" />
      else => <Item name="many" />
    }
  </Panel>

let given =
  <Panel>
    <Item name="y" />
    {kids()}
  </Panel>

hover.source:
import "@nx/visualizer"

/// A node in the tree.
abstract component <Node
  /// Whether it shows.
  visible:bool = true
/>

type ShapeType =
  /// Square corners.
  | Rectangle
  /// Round.
  | Circle

/// A filled shape.
component <Shape extends Node
  /// What the shape draws.
  Type:ShapeType = Rectangle
  /// Words under it.
  label?:string
/> = { <div /> }

/// A task to do.
type Task = { id:string title:string done:bool = false }

/// Something was sent.
action Submitted = { at:int }

/// Where it lives.
type Place = string

visualizer Task = <ElementVisualizer title=title id=id />

/// Doubles.
let twice(n:int): int = { n * 2 }

/// How big.
let size = 3

/// A glowing shape.
let <Glow color:string /> = { <Shape Type=Circle /> }

let root(t:Task) = {
  // A note.
  <Shape Type=Circle label="hi" visible=false />
  <Shape Type={ShapeType.Rectangle} label={t.title} />
  <Shape label={twice(size)} />
  <Glow color="red" />
  <Task id="ship" title="Ship it" />
}

